package com.careernav.service;
import com.careernav.config.AppProperties;
import com.careernav.domain.JobImport;
import com.careernav.entity.JobSourcePolicyEntity;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger; import org.slf4j.LoggerFactory;
import org.springframework.http.MediaType; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
import java.time.LocalDateTime; import java.util.*; import java.util.concurrent.atomic.AtomicLong;
@Component
public class McpJobGateway {
 private static final Logger log=LoggerFactory.getLogger(McpJobGateway.class);
 private final AppProperties properties;private final ObjectMapper mapper;private final RestClient.Builder builder;private final SourcePolicyService policyService;private final AtomicLong id=new AtomicLong(1);
 public McpJobGateway(AppProperties properties,ObjectMapper mapper,RestClient.Builder builder,SourcePolicyService policyService){this.properties=properties;this.mapper=mapper;this.builder=builder;this.policyService=policyService;}
 public boolean enabled(){return properties.getMcp().isEnabled();}
 public List<JobImport> fetchJobs(String keyword,String city,int limit){if(!enabled())return List.of();JobSourcePolicyEntity policy=policyService.require("remote-mcp");policyService.assertAllowed("remote-mcp");policyService.enforceAllowedUrl(policy,properties.getMcp().getEndpoint());Map<String,Object> request=Map.of("jsonrpc","2.0","id",id.getAndIncrement(),"method","tools/call","params",Map.of("name",properties.getMcp().getToolName(),"arguments",Map.of("keyword",keyword==null?"":keyword,"city",city==null?"":city,"limit",limit)));try{policyService.markRequestStarted("remote-mcp");RestClient.RequestBodySpec spec=builder.build().post().uri(properties.getMcp().getEndpoint()).contentType(MediaType.APPLICATION_JSON).header("User-Agent",properties.getCollection().getUserAgent()+" (+mailto:"+properties.getCollection().getContactEmail()+")");if(properties.getMcp().getToken()!=null&&!properties.getMcp().getToken().isBlank())spec.header("Authorization","Bearer "+properties.getMcp().getToken());JsonNode response=spec.body(request).retrieve().body(JsonNode.class);List<JobImport> jobs=parse(response);policyService.markSuccess("remote-mcp");return jobs;}catch(org.springframework.web.client.RestClientResponseException e){policyService.markHttpStatus("remote-mcp",e.getStatusCode().value(),e.getResponseHeaders()==null?null:e.getResponseHeaders().getFirst("Retry-After"));log.warn("MCP job refresh failed: {}",e.getMessage());return List.of();}catch(Exception e){log.warn("MCP job refresh failed: {}",e.getMessage());return List.of();}}
 private List<JobImport> parse(JsonNode response)throws Exception{if(response==null)return List.of();if(response.has("error"))throw new IllegalStateException(response.path("error").path("message").asText("MCP tool call failed"));JsonNode content=response.path("result").path("content");String text=null;if(content.isArray()&&!content.isEmpty())text=content.get(0).path("text").asText(null);JsonNode jobs;if(text!=null&&!text.isBlank())jobs=mapper.readTree(text);else jobs=response.path("result").path("jobs");if(jobs.has("jobs"))jobs=jobs.path("jobs");if(!jobs.isArray())return List.of();List<JobImport> result=new ArrayList<>();for(JsonNode node:jobs)result.add(new JobImport(node.path("externalId").asText(node.path("id").asText(null)),node.path("title").asText(""),node.path("company").asText(""),node.path("city").asText(""),node.path("salary").asText(""),node.path("education").asText("不限"),node.path("experience").asText("不限"),strings(node.path("skills")),strings(node.path("responsibilities")),node.path("description").asText(""),node.path("source").asText("MCP"),node.path("sourceUrl").asText(""),LocalDateTime.now()));return result;}
 private List<String> strings(JsonNode node){if(!node.isArray())return List.of();List<String> values=new ArrayList<>();node.forEach(item->values.add(item.asText()));return values;}
}
